-- TomoModForever 1.2.3 release notes.

TomoMod_RegisterLocale("enUS", {
    ["wn_123_pet"] = "Fixed - Pet happiness icon: it now reads the game's own happiness state (C_PetInfo on Forever), so it changes exactly when Blizzard's pet sheet does. The estimate from the hidden gauge is only a fallback. The tooltip also shows the pet's damage percentage when the game gives it.",
    ["wn_123_flight"] = "New - Flight timer: every Forever flight route is built in, so the bar counts down from your very first flight and the flight master's map shows each destination's duration before you leave. The speed fits itself to your own flights, and a time learned on a route still comes first. /tmf flight checks the routes of the open flight map.",
})

TomoMod_RegisterLocale("frFR", {
    ["wn_123_pet"] = "Corrigé - Icône d'humeur du familier : elle lit maintenant l'état d'humeur du jeu lui-même (C_PetInfo sur Forever), elle change donc exactement en même temps que la fiche du familier Blizzard. L'estimation à partir de la jauge cachée ne sert plus qu'en secours. L'infobulle affiche aussi le pourcentage de dégâts du familier quand le jeu le donne.",
    ["wn_123_flight"] = "Nouveau - Temps de vol : tous les trajets de Forever sont intégrés, la barre fait donc le compte à rebours dès ton premier vol et la carte du maître de vol affiche la durée de chaque destination avant le départ. La vitesse se cale sur tes propres vols, et un temps appris sur un trajet reste prioritaire. /tmf vol vérifie les trajets de la carte ouverte.",
})

TomoMod_RegisterLocale("deDE", {
    ["wn_123_pet"] = "Behoben - Laune-Symbol des Begleiters: Es liest jetzt den Launezustand des Spiels selbst (C_PetInfo auf Forever) und wechselt daher genau zusammen mit Blizzards Begleiterfenster. Die Schätzung aus der versteckten Leiste dient nur noch als Ersatz. Der Tooltip zeigt außerdem den Schadensprozentsatz des Begleiters, wenn das Spiel ihn liefert.",
    ["wn_123_flight"] = "Neu - Flugzeit: Alle Flugrouten von Forever sind eingebaut, die Leiste zählt also schon ab deinem ersten Flug herunter und die Karte des Flugmeisters zeigt vor dem Abflug die Dauer jedes Ziels. Die Geschwindigkeit passt sich deinen eigenen Flügen an, und eine auf einer Route gelernte Zeit hat weiterhin Vorrang. /tmf flight prüft die Routen der offenen Flugkarte.",
})

TomoMod_RegisterLocale("esES", {
    ["wn_123_pet"] = "Corregido - Icono de felicidad de la mascota: ahora lee el estado de felicidad del propio juego (C_PetInfo en Forever), así que cambia exactamente a la vez que la ficha de mascota de Blizzard. La estimación a partir de la barra oculta solo queda como respaldo. La descripción también muestra el porcentaje de daño de la mascota cuando el juego lo da.",
    ["wn_123_flight"] = "Nuevo - Tiempo de vuelo: todas las rutas de vuelo de Forever vienen incluidas, así que la barra cuenta atrás desde tu primer vuelo y el mapa del maestro de vuelo muestra la duración de cada destino antes de salir. La velocidad se ajusta a tus propios vuelos y un tiempo aprendido en una ruta sigue teniendo prioridad. /tmf flight comprueba las rutas del mapa abierto.",
})

TomoMod_RegisterLocale("itIT", {
    ["wn_123_pet"] = "Corretto - Icona dell'umore del famiglio: ora legge lo stato d'umore del gioco stesso (C_PetInfo su Forever), quindi cambia esattamente insieme alla scheda del famiglio Blizzard. La stima dalla barra nascosta resta solo come riserva. Il tooltip mostra anche la percentuale di danni del famiglio quando il gioco la fornisce.",
    ["wn_123_flight"] = "Nuovo - Tempo di volo: tutte le rotte di volo di Forever sono incluse, quindi la barra fa il conto alla rovescia dal tuo primo volo e la mappa del maestro di volo mostra la durata di ogni destinazione prima della partenza. La velocità si adatta ai tuoi voli e un tempo imparato su una rotta resta prioritario. /tmf flight controlla le rotte della mappa aperta.",
})

TomoMod_RegisterLocale("ptBR", {
    ["wn_123_pet"] = "Corrigido - Ícone de felicidade do ajudante: agora lê o estado de felicidade do próprio jogo (C_PetInfo no Forever), então muda exatamente junto com a ficha do ajudante da Blizzard. A estimativa a partir da barra oculta fica só como reserva. A dica também mostra a porcentagem de dano do ajudante quando o jogo a fornece.",
    ["wn_123_flight"] = "Novo - Tempo de voo: todas as rotas de voo do Forever vêm embutidas, então a barra faz a contagem regressiva desde o seu primeiro voo e o mapa do mestre de voo mostra a duração de cada destino antes da partida. A velocidade se ajusta aos seus próprios voos e um tempo aprendido numa rota continua tendo prioridade. /tmf flight verifica as rotas do mapa aberto.",
})
